/bin/bash -lc "node --input-type=module <<'EOF'
import { spawnSync } from 'node:child_process';
import { runCli } from '/output/lib/runCli.mjs';

function captureRun(args) {
  const stdoutChunks = [];
  const stderrChunks = [];
  const io = {
    stdout: { write(chunk) { stdoutChunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk))); return true; } },
    stderr: { write(chunk) { stderrChunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk))); return true; } },
  };
  const code = runCli(['node', 'test11_executable', ...args], io);
  return {
    status: code,
    stdout: Buffer.concat(stdoutChunks),
    stderr: Buffer.concat(stderrChunks),
  };
}

const cases = [
  [],
  ['--help'],
  ['--a', 'x', '--b', 'y', '--c', 'z'],
  ['--a=x', '--b=y', '--c=z'],
  ['--a', '', '--b', 'y', '--c', 'z'],
  ['--a', '--b', 'y', '--c', 'z'],
  ['--a', 'x', '--b', 'y', '--c', 'z', '--d', 'q'],
  ['foo', '--a', 'x'],
  ['--help=value'],
  ['--a', '-1.5', '--b', '-.5', '--c', '-01'],
  ['--a', '1. item1\\n2. item2', '--b', '|h|\\n|-|\\n|v|', '--c', '"'```'"\\ncode\\n"'```'"'],
];

let failures = 0;
for (const args of cases) {
  const expected = spawnSync('/workspace/dataset/test11_executable', args, { stdio: ['ignore', 'pipe', 'pipe'] });
  const actual = captureRun(args);
  const sameStatus = actual.status === (expected.status ?? 0);
  const sameStdout = actual.stdout.equals(expected.stdout);
  const sameStderr = actual.stderr.equals(expected.stderr);
  if ("'!sameStatus || !sameStdout || !sameStderr) {
    failures += 1;
    console.log('"'FAIL', JSON.stringify(args));
    console.log('status', actual.status, expected.status);
    console.log('stdout', JSON.stringify(actual.stdout.toString('utf8')), JSON.stringify(expected.stdout.toString('utf8')));
    console.log('stderr', JSON.stringify(actual.stderr.toString('utf8')), JSON.stringify(expected.stderr.toString('utf8')));
  }
}

if (failures > 0) {
  process.exitCode = 1;
} else {
  console.log('parity-ok');
}
EOF"

